"""Converts a string from a MixedCaseString to a UPPER_SNAKE_CASE_STRING."""
def to_upper_snake_case(s: str) -> str {
    s = s.upper();
    r = '';
    for i in range(0, len(s)) {
        r += s[i] if s[i].isalnum() else '_';
    }
    return r;
}
